  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(productA, 5);
      cart.updateQuantity("a", 3);
      expect(cart.itemCount).toBe(3);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 5);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("a")).toBe(false); // already gone
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      // Mutate snapshot — should not affect cart
      (snap as CartLine[])[0]!.quantity = 999;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 3); // 1000 * 3 = 3000
      cart.add(productB, 2); // 2000 * 2 = 4000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(7000);
    });

    it("returns zero totals for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(0);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(0);
    });

    it("applies discount, then tax on discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(1000),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(600),
      };
      const cart = new Cart({ discountPolicy, taxCalculator });
      cart.add(productA, 5); // subtotal = 5000

      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(5000);
      expect(totals.discountCents).toBe(1000);
      // Tax is called with discounted subtotal (5000 - 1000 = 4000)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(4000, "US");
      expect(totals.taxCents).toBe(600);
    });

    it("clamps discount to [0, subtotal]", () => {
      const over: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy: over });
      cart.add(productA, 1); // subtotal = 1000
      expect(cart.totals().discountCents).toBe(1000);
      expect(cart.totals().totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const negative: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negative });
      cart.add(productA, 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("shipping receives the discounted subtotal and lines", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(productA, 1); // subtotal = 1000, discounted = 800
      cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => -100,
      };
      const cart = new Cart({ taxCalculator });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => 300,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
      });
      cart.add(productA, 2); // subtotal = 2000, discounted = 1500
      const totals = cart.totals();
      expect(totals.totalCents).toBe(1500 + 300 + 200);
    });

    it("uses defaults when no config is provided", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const totals = cart.totals();
      // No discount, no tax, free shipping
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });

    it("uses custom region for tax", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator, region: "FR" });
      cart.add(productA, 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });
  });

  describe("checkout", () => {
    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(4000); // 1000*2 + 2000*1
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(1500) // product a gets new price
          .mockResolvedValueOnce(2500), // product b gets new price
      };
      const result = await cart.checkout({ priceFetcher });
      // New subtotal: 1500*2 + 2500*1 = 5500
      expect(result.totals.subtotalCents).toBe(5500);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, reason: "discontinued" }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InstanceType<typeof InventoryError>;
        expect(invErr.message).toBe("discontinued");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // product a requested 2
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InstanceType<typeof InventoryError>;
        expect(invErr.requested).toBe(2);
        expect(invErr.available).toBe(1);
      }
    });

    it("passes inventory check when fully available", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(4000);
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 4000, no discount, 10% tax = 400
      expect(result.totals.taxCents).toBe(400);
    });

    it("computes async tax on discounted subtotal", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 1000,
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const discountedCart = new Cart({ discountPolicy });
      discountedCart.add(productA, 5); // subtotal 5000, discount 1000, discounted 4000

      const result = await discountedCart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(400); // 10% of 4000
      expect(result.totals.discountCents).toBe(1000);
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const fullCart = new Cart({ shippingCalculator });
      fullCart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await fullCart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });
      // subtotal: 2000, discount: 0, tax: 5% of 2000 = 100, shipping: 500
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.taxCents).toBe(100);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(2600);
    });

    it("generates default InventoryError message with stock info", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InstanceType<typeof InventoryError>;
        expect(invErr.message).toContain("insufficient stock");
        expect(invErr.productId).toBe("a");
      }
    });

    it("does not mutate the cart's internal lines after checkout", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      await cart.checkout({ priceFetcher });
      // Original cart prices should be unchanged
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4000);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects invalid percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0 exact
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → floor → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals the subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount equals zero", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents %i", (amt) => {
      expect(() => new FixedAmountDiscountPolicy(amt)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns 0 when amountCents is zero", () => {
      const policy = new FixedAmountDiscountPolicy(0);
      expect(policy.computeDiscountCents(1000)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // fixed 500
        ],
        "sum",
      );
      expect(policy.computeDiscountCents(10000)).toBe(1500);
    });

    it("each child sees the original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500
        ],
        "sum",
      );
      // sum = 1000 (may exceed subtotal; clamping is done by Cart)
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativeMock = {
        computeDiscountCents: () => -200,
      };
      const policy = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -200 clamped to 0, plus 100 = 100
      expect(policy.computeDiscountCents(500)).toBe(100);
    });

    it("defaults to sum mode when not specified", () => {
      const policy = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining = 500
          new PercentageDiscountPolicy(50), // 50% of 500 = 250, remaining = 250
        ],
        "chain",
      );
      expect(policy.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering matters in chain mode", () => {
      const policyAB = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(300), // 300, remaining = 700
          new PercentageDiscountPolicy(50), // 50% of 700 = 350
        ],
        "chain",
      );
      const policyBA = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining = 500
          new FixedAmountDiscountPolicy(300), // min(300, 500) = 300
        ],
        "chain",
      );
      expect(policyAB.computeDiscountCents(1000)).toBe(650);
      expect(policyBA.computeDiscountCents(1000)).toBe(800);
    });

    it("stops accumulating once remaining reaches zero", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // takes all 500
          new FixedAmountDiscountPolicy(200), // remaining = 0, step = 0
        ],
        "chain",
      );
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativeMock = {
        computeDiscountCents: () => -100,
      };
      const policy = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // first: max(0, -100) = 0, min(0, 500) = 0; remaining stays 500
      // second: min(200, 500) = 200
      expect(policy.computeDiscountCents(500)).toBe(200);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [10000, "FR"],
    [-500, "GB"],
  ])("returns 0 for taxable=%i region=%s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects invalid defaultRate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid rate in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses the region-specific rate", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "JP")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 101 = 20.2 → floor → 20
      expect(calc.computeTaxCents(101, "FR")).toBe(20);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("uses zero default rate when omitted", () => {
      const noDefault = new RegionalTaxCalculator({ US: 0.1 });
      expect(noDefault.computeTaxCents(1000, "UNKNOWN")).toBe(0);
    });
  });
});

