describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // fixed 500
        ],
        "sum",
      );
      expect(policy.computeDiscountCents(10000)).toBe(1500);
    });

    it("each child sees the original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500
        ],
        "sum",
      );
      // sum = 1000 (may exceed subtotal; clamping is done by Cart)
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativeMock = {
        computeDiscountCents: () => -200,
      };
      const policy = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -200 clamped to 0, plus 100 = 100
      expect(policy.computeDiscountCents(500)).toBe(100);
    });

    it("defaults to sum mode when not specified", () => {
      const policy = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining = 500
          new PercentageDiscountPolicy(50), // 50% of 500 = 250, remaining = 250
        ],
        "chain",
      );
      expect(policy.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering matters in chain mode", () => {
      const policyAB = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(300), // 300, remaining = 700
          new PercentageDiscountPolicy(50), // 50% of 700 = 350
        ],
        "chain",
      );
      const policyBA = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining = 500
          new FixedAmountDiscountPolicy(300), // min(300, 500) = 300
        ],
        "chain",
      );
      expect(policyAB.computeDiscountCents(1000)).toBe(650);
      expect(policyBA.computeDiscountCents(1000)).toBe(800);
    });

    it("stops accumulating once remaining reaches zero", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // takes all 500
          new FixedAmountDiscountPolicy(200), // remaining = 0, step = 0
        ],
        "chain",
      );
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativeMock = {
        computeDiscountCents: () => -100,
      };
      const policy = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // first: max(0, -100) = 0, min(0, 500) = 0; remaining stays 500
      // second: min(200, 500) = 200
      expect(policy.computeDiscountCents(500)).toBe(200);
    });
  });
});
"}

