toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 100, weightGrams },
  quantity,
});

const emptyLines: readonly CartLine[] = [];

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents(emptyLines, 0)).toBe(0);
  });

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500)], 10000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents(emptyLines, 10000)).toBe(0);
    });

    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(799);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 4999)).toBe(500);
    });

    it("charges flat fee when no freeOverCents is set", () => {
      const calc = new FlatShippingCalculator(500);
      expect(
        calc.computeShippingCents([makeLine("a", 100)], 999_999),
      ).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents(emptyLines, 5000)).toBe(0);
    });

    it("returns 0 when all items have zero weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 0, 3)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g → first bracket (up to 500g, cost 300)
      expect(calc.computeShippingCents([makeLine("a", 200)], 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // exactly 500g → first bracket
      expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(300);
    });

    it("moves to next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → second bracket (up to 2000g, cost 700)
      expect(calc.computeShippingCents([makeLine("a", 501)], 5000)).toBe(700);
    });

    it("selects the heaviest bracket at its exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 5000g → third bracket
      expect(calc.computeShippingCents([makeLine("a", 5000)], 5000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calc.computeShippingCents([makeLine("a", 6000)], 5000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow is set", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 6000)], 5000)).toBe(1200);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      expect(calc.computeShippingCents([makeLine("a", 200)], 5000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200*2 + 300*1 = 700g → second bracket
      const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });
  });
});

